use kimo_core::commands::{dispatch,Session};use serde_json::json;
#[test]fn raw_light_commands_have_finite_results_and_reject_zero_direction(){let mut ss=Session::new();let args=json!({"normal":[0,0,1],"light":[0,0,1],"view":[0,0,1],"albedo":[0.2,0.3,0.4],"material":{"roughness":0.5,"metal":0,"ior":1.5}});let out=dispatch(&mut ss,"lighting_brdf_sample",&args).unwrap();assert!(out["diffuse"][0].as_f64().unwrap()>0.0);assert!(out["specular"][0].as_f64().unwrap()>0.0);let mut bad=args;bad["normal"]=json!([0,0,0]);assert!(dispatch(&mut ss,"lighting_brdf_sample",&bad).is_err());}
#[test]fn backfacing_light_is_zero_and_raw_disabled_is_zero(){let mut ss=Session::new();let r=dispatch(&mut ss,"lighting_brdf_sample",&json!({"normal":[0,0,1],"light":[0,0,-1],"view":[0,0,1],"albedo":[1,1,1],"material":{}})).unwrap();assert_eq!(r["diffuse"],json!([0.0,0.0,0.0]));let r=dispatch(&mut ss,"lighting_incident_sample",&json!({"definition":{"kind":"point","pos":[0,0,1],"enabled":false},"position":[0,0,0]})).unwrap();assert_eq!(r["incident_rgb"],json!([0.0,0.0,0.0]));}
#[test]fn existing_light_math_unchanged(){let mut ss=Session::new();for rough in [0.0,0.1,0.5,1.0]{let m=kimo_core::lighting::Material{roughness:rough,..Default::default()};let(d,s)=kimo_core::lighting::brdf([0.,0.,1.],[0.,0.,1.],[0.,0.,1.],&m,[0.2;3]);let r=dispatch(&mut ss,"lighting_brdf_sample",&json!({"normal":[0,0,1],"light":[0,0,1],"view":[0,0,1],"albedo":[0.2,0.2,0.2],"material":m})).unwrap();assert_eq!(r["diffuse"],json!(d));assert_eq!(r["specular"],json!(s));}}
